@lru_cache(maxsize=1)
def workshop_html():
    return gzip.decompress(base64.b64decode(_PAYLOAD)).decode("utf-8")

def main():
    import streamlit as st
    st.set_page_config(page_title="AUTOVERSE · Open Workshop", page_icon="🏎️", layout="wide", initial_sidebar_state="collapsed")
    st.markdown("<style>.block-container{padding:.2rem .35rem 0;max-width:none}header[data-testid=stHeader]{display:none}[data-testid=stAppViewContainer]{background:#101316}footer{display:none}</style>",unsafe_allow_html=True)
    height=max(700,min(1600,int(os.environ.get("AUTOVERSE_VIEW_HEIGHT","940"))))
    if hasattr(st,"iframe"):
        st.iframe(workshop_html(),height=height,alt="AUTOVERSE 3D 자유 제작 작업장")
    else:
        import streamlit.components.v1 as components
        components.html(workshop_html(),height=height,scrolling=False)

if __name__ == "__main__":
    if len(sys.argv)>1 and sys.argv[1]=="--export-html":
        target=Path(sys.argv[2] if len(sys.argv)>2 else "AUTOVERSE_WORKSHOP.html")
        target.write_text(workshop_html(),encoding="utf-8")
        print(target.resolve())
    else:
        main()

